PRAGMA foreign_keys=ON;
BEGIN TRANSACTION;
INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk6-01','HSK6-01','HSK 6 · Đề 01','hsk','HSK 6',70,'published',1,'Đề luyện HSK 6 số 01 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk6-01-q01','seed-hsk6-01',1,'single_choice','Pinyin phù hợp với “评估” là phương án nào?','Pinyin của “评估” là “pínggū”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “đánh giá”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-01-q02','seed-hsk6-01',2,'single_choice','Chọn từ Hán ngữ có nghĩa “phụ thuộc”.','Từ phù hợp là “依赖”, đọc là yīlài. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-01-q03','seed-hsk6-01',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “持续 — chíxù”, nghĩa là “liên tục”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-01-q04','seed-hsk6-01',4,'single_choice','Từ “目标” gần nghĩa nhất với phương án nào?','“目标” (mùbiāo) có nghĩa là “mục tiêu”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-01-q05','seed-hsk6-01',5,'single_choice','Pinyin phù hợp với “机制” là phương án nào?','Pinyin của “机制” là “jīzhì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cơ chế”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-01-q06','seed-hsk6-01',6,'single_choice','Chọn từ Hán ngữ có nghĩa “cốt lõi”.','Từ phù hợp là “核心”, đọc là héxīn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-01-q07','seed-hsk6-01',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “维持 — wéichí”, nghĩa là “duy trì”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-01-q08','seed-hsk6-01',8,'single_choice','Từ “实施” gần nghĩa nhất với phương án nào?','“实施” (shíshī) có nghĩa là “thực hiện”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-01-q09','seed-hsk6-01',9,'single_choice','Pinyin phù hợp với “识别” là phương án nào?','Pinyin của “识别” là “shíbié”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nhận diện”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-01-q10','seed-hsk6-01',10,'single_choice','Chọn từ Hán ngữ có nghĩa “chuyển đổi”.','Từ phù hợp là “转换”, đọc là zhuǎnhuàn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-01-q11','seed-hsk6-01',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “策略 — cèlüè”, nghĩa là “chiến lược”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-01-q12','seed-hsk6-01',12,'single_choice','Từ “创新” gần nghĩa nhất với phương án nào?','“创新” (chuàngxīn) có nghĩa là “đổi mới”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-01-q13','seed-hsk6-01',13,'single_choice','Pinyin phù hợp với “结构” là phương án nào?','Pinyin của “结构” là “jiégòu”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cấu trúc”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-01-q14','seed-hsk6-01',14,'single_choice','Chọn từ Hán ngữ có nghĩa “hoàn thiện”.','Từ phù hợp là “完善”, đọc là wánshàn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-01-q15','seed-hsk6-01',15,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “规范 — guīfàn”, nghĩa là “chuẩn hóa”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-01-q16','seed-hsk6-01',16,'single_choice','Từ “平衡” gần nghĩa nhất với phương án nào?','“平衡” (pínghéng) có nghĩa là “cân bằng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-01-q17','seed-hsk6-01',17,'single_choice','Pinyin phù hợp với “反馈” là phương án nào?','Pinyin của “反馈” là “fǎnkuì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phản hồi”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-01-q18','seed-hsk6-01',18,'single_choice','Chọn từ Hán ngữ có nghĩa “điều phối”.','Từ phù hợp là “协调”, đọc là xiétiáo. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-01-q19','seed-hsk6-01',19,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “综合 — zōnghé”, nghĩa là “tổng hợp”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-01-q20','seed-hsk6-01',20,'single_choice','Từ “逻辑” gần nghĩa nhất với phương án nào?','“逻辑” (luójí) có nghĩa là “logic”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
