INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk6-02','HSK6-02','HSK 6 · Đề 02','hsk','HSK 6',70,'published',1,'Đề luyện HSK 6 số 02 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk6-02-q01','seed-hsk6-02',1,'single_choice','Pinyin phù hợp với “转换” là phương án nào?','Pinyin của “转换” là “zhuǎnhuàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “chuyển đổi”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-02-q02','seed-hsk6-02',2,'single_choice','Chọn từ Hán ngữ có nghĩa “chiến lược”.','Từ phù hợp là “策略”, đọc là cèlüè. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-02-q03','seed-hsk6-02',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “创新 — chuàngxīn”, nghĩa là “đổi mới”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-02-q04','seed-hsk6-02',4,'single_choice','Từ “结构” gần nghĩa nhất với phương án nào?','“结构” (jiégòu) có nghĩa là “cấu trúc”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-02-q05','seed-hsk6-02',5,'single_choice','Pinyin phù hợp với “完善” là phương án nào?','Pinyin của “完善” là “wánshàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hoàn thiện”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-02-q06','seed-hsk6-02',6,'single_choice','Chọn từ Hán ngữ có nghĩa “chuẩn hóa”.','Từ phù hợp là “规范”, đọc là guīfàn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
