INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk6-03','HSK6-03','HSK 6 · Đề 03','hsk','HSK 6',70,'published',1,'Đề luyện HSK 6 số 03 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk6-03-q01','seed-hsk6-03',1,'single_choice','Pinyin phù hợp với “综合” là phương án nào?','Pinyin của “综合” là “zōnghé”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “tổng hợp”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-03-q02','seed-hsk6-03',2,'single_choice','Chọn từ Hán ngữ có nghĩa “logic”.','Từ phù hợp là “逻辑”, đọc là luójí. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-03-q03','seed-hsk6-03',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “评估 — pínggū”, nghĩa là “đánh giá”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-03-q04','seed-hsk6-03',4,'single_choice','Từ “依赖” gần nghĩa nhất với phương án nào?','“依赖” (yīlài) có nghĩa là “phụ thuộc”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-03-q05','seed-hsk6-03',5,'single_choice','Pinyin phù hợp với “持续” là phương án nào?','Pinyin của “持续” là “chíxù”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “liên tục”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-03-q06','seed-hsk6-03',6,'single_choice','Chọn từ Hán ngữ có nghĩa “mục tiêu”.','Từ phù hợp là “目标”, đọc là mùbiāo. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-03-q07','seed-hsk6-03',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “机制 — jīzhì”, nghĩa là “cơ chế”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-03-q08','seed-hsk6-03',8,'single_choice','Từ “核心” gần nghĩa nhất với phương án nào?','“核心” (héxīn) có nghĩa là “cốt lõi”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-03-q09','seed-hsk6-03',9,'single_choice','Pinyin phù hợp với “维持” là phương án nào?','Pinyin của “维持” là “wéichí”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “duy trì”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-03-q10','seed-hsk6-03',10,'single_choice','Chọn từ Hán ngữ có nghĩa “thực hiện”.','Từ phù hợp là “实施”, đọc là shíshī. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-03-q11','seed-hsk6-03',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “识别 — shíbié”, nghĩa là “nhận diện”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-03-q12','seed-hsk6-03',12,'single_choice','Từ “转换” gần nghĩa nhất với phương án nào?','“转换” (zhuǎnhuàn) có nghĩa là “chuyển đổi”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-03-q13','seed-hsk6-03',13,'single_choice','Pinyin phù hợp với “策略” là phương án nào?','Pinyin của “策略” là “cèlüè”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “chiến lược”.',NULL,NULL,0,1,'',datetime('now')),
