INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk6-04','HSK6-04','HSK 6 · Đề 04','hsk','HSK 6',70,'published',1,'Đề luyện HSK 6 số 04 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk6-04-q01','seed-hsk6-04',1,'single_choice','Pinyin phù hợp với “实施” là phương án nào?','Pinyin của “实施” là “shíshī”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thực hiện”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-04-q02','seed-hsk6-04',2,'single_choice','Chọn từ Hán ngữ có nghĩa “nhận diện”.','Từ phù hợp là “识别”, đọc là shíbié. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-04-q03','seed-hsk6-04',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “转换 — zhuǎnhuàn”, nghĩa là “chuyển đổi”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-04-q04','seed-hsk6-04',4,'single_choice','Từ “策略” gần nghĩa nhất với phương án nào?','“策略” (cèlüè) có nghĩa là “chiến lược”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-04-q05','seed-hsk6-04',5,'single_choice','Pinyin phù hợp với “创新” là phương án nào?','Pinyin của “创新” là “chuàngxīn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “đổi mới”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-04-q06','seed-hsk6-04',6,'single_choice','Chọn từ Hán ngữ có nghĩa “cấu trúc”.','Từ phù hợp là “结构”, đọc là jiégòu. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-04-q07','seed-hsk6-04',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “完善 — wánshàn”, nghĩa là “hoàn thiện”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-04-q08','seed-hsk6-04',8,'single_choice','Từ “规范” gần nghĩa nhất với phương án nào?','“规范” (guīfàn) có nghĩa là “chuẩn hóa”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-04-q09','seed-hsk6-04',9,'single_choice','Pinyin phù hợp với “平衡” là phương án nào?','Pinyin của “平衡” là “pínghéng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cân bằng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-04-q10','seed-hsk6-04',10,'single_choice','Chọn từ Hán ngữ có nghĩa “phản hồi”.','Từ phù hợp là “反馈”, đọc là fǎnkuì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-04-q11','seed-hsk6-04',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “协调 — xiétiáo”, nghĩa là “điều phối”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-04-q12','seed-hsk6-04',12,'single_choice','Từ “综合” gần nghĩa nhất với phương án nào?','“综合” (zōnghé) có nghĩa là “tổng hợp”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-04-q13','seed-hsk6-04',13,'single_choice','Pinyin phù hợp với “逻辑” là phương án nào?','Pinyin của “逻辑” là “luójí”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “logic”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-04-q14','seed-hsk6-04',14,'single_choice','Chọn từ Hán ngữ có nghĩa “đánh giá”.','Từ phù hợp là “评估”, đọc là pínggū. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-04-q15','seed-hsk6-04',15,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “依赖 — yīlài”, nghĩa là “phụ thuộc”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
