('seed-hsk6-06-q21','seed-hsk6-06',21,'single_choice','Pinyin phù hợp với “核心” là phương án nào?','Pinyin của “核心” là “héxīn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cốt lõi”.',NULL,NULL,0,1,'',datetime('now')),
