('seed-hsk6-07-q16','seed-hsk6-07',16,'single_choice','Từ “转换” gần nghĩa nhất với phương án nào?','“转换” (zhuǎnhuàn) có nghĩa là “chuyển đổi”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
