INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk6-08','HSK6-08','HSK 6 · Đề 08','hsk','HSK 6',70,'published',1,'Đề luyện HSK 6 số 08 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk6-08-q01','seed-hsk6-08',1,'single_choice','Pinyin phù hợp với “目标” là phương án nào?','Pinyin của “目标” là “mùbiāo”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “mục tiêu”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-08-q02','seed-hsk6-08',2,'single_choice','Chọn từ Hán ngữ có nghĩa “cơ chế”.','Từ phù hợp là “机制”, đọc là jīzhì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-08-q03','seed-hsk6-08',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “核心 — héxīn”, nghĩa là “cốt lõi”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-08-q04','seed-hsk6-08',4,'single_choice','Từ “维持” gần nghĩa nhất với phương án nào?','“维持” (wéichí) có nghĩa là “duy trì”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-08-q05','seed-hsk6-08',5,'single_choice','Pinyin phù hợp với “实施” là phương án nào?','Pinyin của “实施” là “shíshī”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thực hiện”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-08-q06','seed-hsk6-08',6,'single_choice','Chọn từ Hán ngữ có nghĩa “nhận diện”.','Từ phù hợp là “识别”, đọc là shíbié. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-08-q07','seed-hsk6-08',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “转换 — zhuǎnhuàn”, nghĩa là “chuyển đổi”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-08-q08','seed-hsk6-08',8,'single_choice','Từ “策略” gần nghĩa nhất với phương án nào?','“策略” (cèlüè) có nghĩa là “chiến lược”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-08-q09','seed-hsk6-08',9,'single_choice','Pinyin phù hợp với “创新” là phương án nào?','Pinyin của “创新” là “chuàngxīn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “đổi mới”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-08-q10','seed-hsk6-08',10,'single_choice','Chọn từ Hán ngữ có nghĩa “cấu trúc”.','Từ phù hợp là “结构”, đọc là jiégòu. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-08-q11','seed-hsk6-08',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “完善 — wánshàn”, nghĩa là “hoàn thiện”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-08-q12','seed-hsk6-08',12,'single_choice','Từ “规范” gần nghĩa nhất với phương án nào?','“规范” (guīfàn) có nghĩa là “chuẩn hóa”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
