('seed-hsk6-08-q29','seed-hsk6-08',29,'single_choice','Pinyin phù hợp với “创新” là phương án nào?','Pinyin của “创新” là “chuàngxīn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “đổi mới”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-08-q30','seed-hsk6-08',30,'single_choice','Chọn từ Hán ngữ có nghĩa “cấu trúc”.','Từ phù hợp là “结构”, đọc là jiégòu. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
