('seed-hsk6-09-q33','seed-hsk6-09',33,'single_choice','Pinyin phù hợp với “机制” là phương án nào?','Pinyin của “机制” là “jīzhì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cơ chế”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-09-q34','seed-hsk6-09',34,'single_choice','Chọn từ Hán ngữ có nghĩa “cốt lõi”.','Từ phù hợp là “核心”, đọc là héxīn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
