('seed-hsk6-09-q37','seed-hsk6-09',37,'single_choice','Pinyin phù hợp với “识别” là phương án nào?','Pinyin của “识别” là “shíbié”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nhận diện”.',NULL,NULL,0,1,'',datetime('now')),
