INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk6-10','HSK6-10','HSK 6 · Đề 10','hsk','HSK 6',70,'published',1,'Đề luyện HSK 6 số 10 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk6-10-q01','seed-hsk6-10',1,'single_choice','Pinyin phù hợp với “依赖” là phương án nào?','Pinyin của “依赖” là “yīlài”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phụ thuộc”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-10-q02','seed-hsk6-10',2,'single_choice','Chọn từ Hán ngữ có nghĩa “liên tục”.','Từ phù hợp là “持续”, đọc là chíxù. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-10-q03','seed-hsk6-10',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “目标 — mùbiāo”, nghĩa là “mục tiêu”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-10-q04','seed-hsk6-10',4,'single_choice','Từ “机制” gần nghĩa nhất với phương án nào?','“机制” (jīzhì) có nghĩa là “cơ chế”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-10-q05','seed-hsk6-10',5,'single_choice','Pinyin phù hợp với “核心” là phương án nào?','Pinyin của “核心” là “héxīn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cốt lõi”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-10-q06','seed-hsk6-10',6,'single_choice','Chọn từ Hán ngữ có nghĩa “duy trì”.','Từ phù hợp là “维持”, đọc là wéichí. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-10-q07','seed-hsk6-10',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “实施 — shíshī”, nghĩa là “thực hiện”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-10-q08','seed-hsk6-10',8,'single_choice','Từ “识别” gần nghĩa nhất với phương án nào?','“识别” (shíbié) có nghĩa là “nhận diện”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-10-q09','seed-hsk6-10',9,'single_choice','Pinyin phù hợp với “转换” là phương án nào?','Pinyin của “转换” là “zhuǎnhuàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “chuyển đổi”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-10-q10','seed-hsk6-10',10,'single_choice','Chọn từ Hán ngữ có nghĩa “chiến lược”.','Từ phù hợp là “策略”, đọc là cèlüè. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-10-q11','seed-hsk6-10',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “创新 — chuàngxīn”, nghĩa là “đổi mới”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
