('seed-hsk6-10-q37','seed-hsk6-10',37,'single_choice','Pinyin phù hợp với “协调” là phương án nào?','Pinyin của “协调” là “xiétiáo”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “điều phối”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-10-q38','seed-hsk6-10',38,'single_choice','Chọn từ Hán ngữ có nghĩa “tổng hợp”.','Từ phù hợp là “综合”, đọc là zōnghé. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-10-q39','seed-hsk6-10',39,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “逻辑 — luójí”, nghĩa là “logic”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-10-q40','seed-hsk6-10',40,'single_choice','Từ “评估” gần nghĩa nhất với phương án nào?','“评估” (pínggū) có nghĩa là “đánh giá”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-10-q41','seed-hsk6-10',41,'single_choice','Pinyin phù hợp với “依赖” là phương án nào?','Pinyin của “依赖” là “yīlài”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phụ thuộc”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-10-q42','seed-hsk6-10',42,'single_choice','Chọn từ Hán ngữ có nghĩa “liên tục”.','Từ phù hợp là “持续”, đọc là chíxù. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-10-q43','seed-hsk6-10',43,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “目标 — mùbiāo”, nghĩa là “mục tiêu”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-10-q44','seed-hsk6-10',44,'single_choice','Từ “机制” gần nghĩa nhất với phương án nào?','“机制” (jīzhì) có nghĩa là “cơ chế”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-10-q45','seed-hsk6-10',45,'single_choice','Pinyin phù hợp với “核心” là phương án nào?','Pinyin của “核心” là “héxīn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cốt lõi”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-10-q46','seed-hsk6-10',46,'single_choice','Chọn từ Hán ngữ có nghĩa “duy trì”.','Từ phù hợp là “维持”, đọc là wéichí. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-10-q47','seed-hsk6-10',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “实施 — shíshī”, nghĩa là “thực hiện”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-10-q48','seed-hsk6-10',48,'single_choice','Từ “识别” gần nghĩa nhất với phương án nào?','“识别” (shíbié) có nghĩa là “nhận diện”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-10-q49','seed-hsk6-10',49,'single_choice','Pinyin phù hợp với “转换” là phương án nào?','Pinyin của “转换” là “zhuǎnhuàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “chuyển đổi”.',NULL,NULL,0,1,'',datetime('now')),
