INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk6-11','HSK6-11','HSK 6 · Đề 11','hsk','HSK 6',70,'published',1,'Đề luyện HSK 6 số 11 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk6-11-q01','seed-hsk6-11',1,'single_choice','Pinyin phù hợp với “策略” là phương án nào?','Pinyin của “策略” là “cèlüè”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “chiến lược”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-11-q02','seed-hsk6-11',2,'single_choice','Chọn từ Hán ngữ có nghĩa “đổi mới”.','Từ phù hợp là “创新”, đọc là chuàngxīn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-11-q03','seed-hsk6-11',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “结构 — jiégòu”, nghĩa là “cấu trúc”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-11-q04','seed-hsk6-11',4,'single_choice','Từ “完善” gần nghĩa nhất với phương án nào?','“完善” (wánshàn) có nghĩa là “hoàn thiện”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-11-q05','seed-hsk6-11',5,'single_choice','Pinyin phù hợp với “规范” là phương án nào?','Pinyin của “规范” là “guīfàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “chuẩn hóa”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-11-q06','seed-hsk6-11',6,'single_choice','Chọn từ Hán ngữ có nghĩa “cân bằng”.','Từ phù hợp là “平衡”, đọc là pínghéng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-11-q07','seed-hsk6-11',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “反馈 — fǎnkuì”, nghĩa là “phản hồi”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-11-q08','seed-hsk6-11',8,'single_choice','Từ “协调” gần nghĩa nhất với phương án nào?','“协调” (xiétiáo) có nghĩa là “điều phối”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-11-q09','seed-hsk6-11',9,'single_choice','Pinyin phù hợp với “综合” là phương án nào?','Pinyin của “综合” là “zōnghé”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “tổng hợp”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-11-q10','seed-hsk6-11',10,'single_choice','Chọn từ Hán ngữ có nghĩa “logic”.','Từ phù hợp là “逻辑”, đọc là luójí. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-11-q11','seed-hsk6-11',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “评估 — pínggū”, nghĩa là “đánh giá”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-11-q12','seed-hsk6-11',12,'single_choice','Từ “依赖” gần nghĩa nhất với phương án nào?','“依赖” (yīlài) có nghĩa là “phụ thuộc”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-11-q13','seed-hsk6-11',13,'single_choice','Pinyin phù hợp với “持续” là phương án nào?','Pinyin của “持续” là “chíxù”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “liên tục”.',NULL,NULL,0,1,'',datetime('now')),
