('seed-hsk6-11-q41','seed-hsk6-11',41,'single_choice','Pinyin phù hợp với “策略” là phương án nào?','Pinyin của “策略” là “cèlüè”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “chiến lược”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-11-q42','seed-hsk6-11',42,'single_choice','Chọn từ Hán ngữ có nghĩa “đổi mới”.','Từ phù hợp là “创新”, đọc là chuàngxīn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-11-q43','seed-hsk6-11',43,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “结构 — jiégòu”, nghĩa là “cấu trúc”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-11-q44','seed-hsk6-11',44,'single_choice','Từ “完善” gần nghĩa nhất với phương án nào?','“完善” (wánshàn) có nghĩa là “hoàn thiện”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-11-q45','seed-hsk6-11',45,'single_choice','Pinyin phù hợp với “规范” là phương án nào?','Pinyin của “规范” là “guīfàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “chuẩn hóa”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-11-q46','seed-hsk6-11',46,'single_choice','Chọn từ Hán ngữ có nghĩa “cân bằng”.','Từ phù hợp là “平衡”, đọc là pínghéng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-11-q47','seed-hsk6-11',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “反馈 — fǎnkuì”, nghĩa là “phản hồi”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-11-q48','seed-hsk6-11',48,'single_choice','Từ “协调” gần nghĩa nhất với phương án nào?','“协调” (xiétiáo) có nghĩa là “điều phối”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-11-q49','seed-hsk6-11',49,'single_choice','Pinyin phù hợp với “综合” là phương án nào?','Pinyin của “综合” là “zōnghé”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “tổng hợp”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-11-q50','seed-hsk6-11',50,'single_choice','Chọn từ Hán ngữ có nghĩa “logic”.','Từ phù hợp là “逻辑”, đọc là luójí. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
