('seed-hsk6-12-q45','seed-hsk6-12',45,'single_choice','Pinyin phù hợp với “目标” là phương án nào?','Pinyin của “目标” là “mùbiāo”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “mục tiêu”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-12-q46','seed-hsk6-12',46,'single_choice','Chọn từ Hán ngữ có nghĩa “cơ chế”.','Từ phù hợp là “机制”, đọc là jīzhì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-12-q47','seed-hsk6-12',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “核心 — héxīn”, nghĩa là “cốt lõi”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-12-q48','seed-hsk6-12',48,'single_choice','Từ “维持” gần nghĩa nhất với phương án nào?','“维持” (wéichí) có nghĩa là “duy trì”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-12-q49','seed-hsk6-12',49,'single_choice','Pinyin phù hợp với “实施” là phương án nào?','Pinyin của “实施” là “shíshī”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thực hiện”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-12-q50','seed-hsk6-12',50,'single_choice','Chọn từ Hán ngữ có nghĩa “nhận diện”.','Từ phù hợp là “识别”, đọc là shíbié. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
