('seed-hsk6-13-q49','seed-hsk6-13',49,'single_choice','Pinyin phù hợp với “反馈” là phương án nào?','Pinyin của “反馈” là “fǎnkuì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phản hồi”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-13-q50','seed-hsk6-13',50,'single_choice','Chọn từ Hán ngữ có nghĩa “điều phối”.','Từ phù hợp là “协调”, đọc là xiétiáo. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
