INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk6-14','HSK6-14','HSK 6 · Đề 14','hsk','HSK 6',70,'published',1,'Đề luyện HSK 6 số 14 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk6-14-q01','seed-hsk6-14',1,'single_choice','Pinyin phù hợp với “协调” là phương án nào?','Pinyin của “协调” là “xiétiáo”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “điều phối”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-14-q02','seed-hsk6-14',2,'single_choice','Chọn từ Hán ngữ có nghĩa “tổng hợp”.','Từ phù hợp là “综合”, đọc là zōnghé. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-14-q03','seed-hsk6-14',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “逻辑 — luójí”, nghĩa là “logic”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-14-q04','seed-hsk6-14',4,'single_choice','Từ “评估” gần nghĩa nhất với phương án nào?','“评估” (pínggū) có nghĩa là “đánh giá”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-14-q05','seed-hsk6-14',5,'single_choice','Pinyin phù hợp với “依赖” là phương án nào?','Pinyin của “依赖” là “yīlài”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phụ thuộc”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-14-q06','seed-hsk6-14',6,'single_choice','Chọn từ Hán ngữ có nghĩa “liên tục”.','Từ phù hợp là “持续”, đọc là chíxù. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-14-q07','seed-hsk6-14',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “目标 — mùbiāo”, nghĩa là “mục tiêu”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-14-q08','seed-hsk6-14',8,'single_choice','Từ “机制” gần nghĩa nhất với phương án nào?','“机制” (jīzhì) có nghĩa là “cơ chế”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-14-q09','seed-hsk6-14',9,'single_choice','Pinyin phù hợp với “核心” là phương án nào?','Pinyin của “核心” là “héxīn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cốt lõi”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-14-q10','seed-hsk6-14',10,'single_choice','Chọn từ Hán ngữ có nghĩa “duy trì”.','Từ phù hợp là “维持”, đọc là wéichí. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-14-q11','seed-hsk6-14',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “实施 — shíshī”, nghĩa là “thực hiện”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-14-q12','seed-hsk6-14',12,'single_choice','Từ “识别” gần nghĩa nhất với phương án nào?','“识别” (shíbié) có nghĩa là “nhận diện”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-14-q13','seed-hsk6-14',13,'single_choice','Pinyin phù hợp với “转换” là phương án nào?','Pinyin của “转换” là “zhuǎnhuàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “chuyển đổi”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-14-q14','seed-hsk6-14',14,'single_choice','Chọn từ Hán ngữ có nghĩa “chiến lược”.','Từ phù hợp là “策略”, đọc là cèlüè. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-14-q15','seed-hsk6-14',15,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “创新 — chuàngxīn”, nghĩa là “đổi mới”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-14-q16','seed-hsk6-14',16,'single_choice','Từ “结构” gần nghĩa nhất với phương án nào?','“结构” (jiégòu) có nghĩa là “cấu trúc”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-14-q17','seed-hsk6-14',17,'single_choice','Pinyin phù hợp với “完善” là phương án nào?','Pinyin của “完善” là “wánshàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hoàn thiện”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-14-q18','seed-hsk6-14',18,'single_choice','Chọn từ Hán ngữ có nghĩa “chuẩn hóa”.','Từ phù hợp là “规范”, đọc là guīfàn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
