('seed-hsk6-14-q20','seed-hsk6-14',20,'single_choice','Từ “反馈” gần nghĩa nhất với phương án nào?','“反馈” (fǎnkuì) có nghĩa là “phản hồi”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
