INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk6-17','HSK6-17','HSK 6 · Đề 17','hsk','HSK 6',70,'published',1,'Đề luyện HSK 6 số 17 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk6-17-q01','seed-hsk6-17',1,'single_choice','Pinyin phù hợp với “机制” là phương án nào?','Pinyin của “机制” là “jīzhì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cơ chế”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-17-q02','seed-hsk6-17',2,'single_choice','Chọn từ Hán ngữ có nghĩa “cốt lõi”.','Từ phù hợp là “核心”, đọc là héxīn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-17-q03','seed-hsk6-17',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “维持 — wéichí”, nghĩa là “duy trì”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-17-q04','seed-hsk6-17',4,'single_choice','Từ “实施” gần nghĩa nhất với phương án nào?','“实施” (shíshī) có nghĩa là “thực hiện”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-17-q05','seed-hsk6-17',5,'single_choice','Pinyin phù hợp với “识别” là phương án nào?','Pinyin của “识别” là “shíbié”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nhận diện”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-17-q06','seed-hsk6-17',6,'single_choice','Chọn từ Hán ngữ có nghĩa “chuyển đổi”.','Từ phù hợp là “转换”, đọc là zhuǎnhuàn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-17-q07','seed-hsk6-17',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “策略 — cèlüè”, nghĩa là “chiến lược”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-17-q08','seed-hsk6-17',8,'single_choice','Từ “创新” gần nghĩa nhất với phương án nào?','“创新” (chuàngxīn) có nghĩa là “đổi mới”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 6.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-17-q09','seed-hsk6-17',9,'single_choice','Pinyin phù hợp với “结构” là phương án nào?','Pinyin của “结构” là “jiégòu”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “cấu trúc”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-17-q10','seed-hsk6-17',10,'single_choice','Chọn từ Hán ngữ có nghĩa “hoàn thiện”.','Từ phù hợp là “完善”, đọc là wánshàn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk6-17-q11','seed-hsk6-17',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “规范 — guīfàn”, nghĩa là “chuẩn hóa”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
